package abstraction_interfaces.assigment_problems;

import java.util.*;public class HomeApplianceEnergyReport {interface Saver{boolean supportsSaver();}static class Appliance{String name;double watts,hours;boolean saver;Appliance(String n,double w,double h,boolean s){name=n;watts=w;hours=h;saver=s;}double units(){return watts*hours/1000*(saver?.75:1);}double cost(){return units()*8;}}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next();double h=s.nextDouble();boolean saver=s.hasNext("SAVER");if(saver)s.next();boolean supported=t.equals("AC")||t.equals("WASHER");if(saver&&!supported){System.out.println(t+": saver mode not supported");continue;}double w=t.equals("FRIDGE")?150:t.equals("AC")?1500:t.equals("TV")?100:500;Appliance a=new Appliance(t,w,h,saver);System.out.printf(Locale.US,"%s: Units=%.2f Cost=%.2f%n",t,a.units(),a.cost());total+=a.cost();}System.out.printf(Locale.US,"Total Cost: %.2f%n",total);}}
